files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8892b0;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  background: var(--card);
  border: 4px solid var(--accent);
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 8px 8px 0 rgba(233, 69, 96, 0.3);
}
h1 {
  font-size: 20px;
  text-align: center;
  margin-bottom: 24px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}
.field { margin-bottom: 20px; }
label {
  display: block;
  margin-bottom: 8px;
  font-size: 16px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}
input, select {
  width: 100%;
  padding: 12px;
  font-family: inherit;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  border: 2px solid var(--muted);
  outline: none;
}
input:focus, select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}
select { cursor: pointer; }
button {
  width: 100%;
  padding: 14px;
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 2px;
  background: var(--accent);
  color: var(--bg);
  border: none;
  cursor: pointer;
  transition: transform 0.05s, background 0.15s;
}
button:hover { background: #ff6b81; }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
button:active { transform: translate(2px, 2px); background: #c73650; }
.result-box {
  margin-top: 24px;
  padding: 16px;
  background: var(--bg);
  border: 2px dashed var(--muted);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}
.result-label {
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}
#result {
  font-size: 22px;
  font-weight: bold;
  color: var(--accent);
  word-break: break-all;
}
.formula {
  margin-top: 20px;
  font-size: 13px;
  text-align: center;
  color: var(--muted);
  line-height: 1.5;
}
@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  h1 { font-size: 18px; }
}

const tempInput = document.getElementById('temperature');
const direction = document.getElementById('direction');
const convertBtn = document.getElementById('convert');
const resultEl = document.getElementById('result');

function convert() {
  const raw = tempInput.value.trim();
  const x = parseFloat(raw);

  if (raw === '' || !isFinite(x)) {
    resultEl.textContent = 'Error';
    return;
  }

  let out;
  if (direction.value === 'c-to-f') {
    out = x * 9 / 5 + 32;
  } else {
    out = (x - 32) * 5 / 9;
  }

  if (!isFinite(out)) {
    resultEl.textContent = 'Error';
    return;
  }

  resultEl.textContent = out.toFixed(2);
}

convertBtn.addEventListener('click', convert);

tempInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') convert();
});
